def write_introduction(w):
 w.structural('ВВЕДЕНИЕ')
 paras(w,
 'Обслуживание физических лиц в отделениях банка требует согласованного учёта клиентов, счетов, банковских карт, переводов и кредитных договоров. Каждое обращение связано с проверкой оснований, изменением учётных данных и подготовкой документа для клиента. Ошибка в одной из связанных записей может привести к неверному остатку, повторному проведению перевода или расхождению графика платежей с условиями договора.',
 'При раздельном ведении сведений сотрудники затрачивают время на повторный ввод реквизитов и сверку результатов. Руководителю операционного направления необходимо обеспечить правильность и своевременность обслуживания при ограниченном кадровом ресурсе. Автоматизация повторяемых проверок и подготовки документов рассматривается как способ сократить ручной труд с сохранением контроля над банковскими операциями.',
 'Цель работы — спроектировать банковскую информационную систему, обеспечивающую согласованное оформление счетов, карт, внутрибанковских переводов и утверждённых кредитных договоров. Объект рассмотрения — операционное обслуживание физических лиц в отделениях банка. Предмет проектирования — данные, функции и программные средства учёта операций, формирования документов и контроля результатов.',
 'Для достижения цели определены назначение и условия применения системы, требования к результатам обслуживания, модели данных, функций и процессов. Архитектура и технический проект устанавливают ответственность компонентов, правила обработки данных и интерфейсы программных модулей. Разработанные методики предусматривают проверку корректности операций и сравнение трудозатрат на обслуживание.')


def paras(w,*texts):
 for text in texts:w.p(text)

def sub(w,title,*texts):w.h(title);paras(w,*texts)

def write_problem(w,table,quality):
 w.page('1 Предметная область и требования к системе',1)
 sub(w,'1.1 Характеристика деятельности банка',
 'Банк обслуживает физических лиц через отделения. Сотрудники ведут сведения о клиентах и счетах, оформляют карты, исполняют внутрибанковские переводы и регистрируют утверждённые кредитные договоры. Каждое обращение имеет основание, реквизиты, сумму или условия, исполнителя и документ с результатом.',
 'Типовой порядок включает установление клиента, выбор его счёта, проверку основания и допустимости операции, регистрацию результата и выдачу документа. Сотрудник проверяет представленные основания и принимает решения в пределах полномочий. Программа поддерживает его действия общими данными, проверками, расчётами и документированием.',
 BUSINESS_PROBLEM,
 'Повторный ввод реквизитов и ручное согласование связанных записей увеличивают трудозатраты. Ускорение одного действия может перенести затраты на исправления и последующую сверку. Поэтому результат обслуживания рассматривается вместе с расходом труда на полный цикл и сохранностью учётных сведений.')
 sub(w,'1.2 Назначение и участники системы',
 'Система предназначена для информационного обеспечения операционного обслуживания физических лиц: ведения клиентов и счетов, обслуживания карт, учёта переводов, регистрации кредитных договоров, подготовки документов и контроля. Основной результат — правильно завершённое обращение с согласованным состоянием учёта.',
 'Заказчиком и лицом, принимающим решение о приёмке, выступает '+OWNER+'. Ему необходимо завершать обращения своевременно и правильно при заданном составе сотрудников. Клиенту нужен верный документ, сотруднику — допустимый и устанавливаемый результат операции, контролёру — основания и история изменений.')
 table(w,'Участники и их задачи',['Участник','Задачи и ответственность'],[
 ('Клиент','Предоставляет распоряжение и необходимые сведения; получает подтверждение, выписку или график'),
 ('Оператор','Проверяет основания; ведёт клиентов и счета, обслуживает карты и переводы'),
 ('Кредитный специалист','Регистрирует утверждённые условия договора и основание его закрытия'),
 ('Контролёр','Получает разрешённые сведения, проверяет историю и независимую сверку'),
 ('Администратор','Ведёт доступ и справочники; обеспечивает запуск и восстановление'),
 ('Руководитель','Определяет регламент, допустимый расход труда и условия приёмки; получает сведения в пределах роли контролёра')],[39,126])
 paras(w,'Система включает исполнителей, регламент и информационные средства. Программный продукт реализует обработку данных, обязательные проверки, расчёты и подготовку документов; его состав определяется назначением и условиями применения [13, 14].')
 table(w,'Деятельность, система и программный продукт',['Объект','Назначение и граница'],EXTERNAL,[39,126])
 paras(w,HYPOTHESIS,
 'Для проверки Г0 сопоставляются ручной порядок А и процесс Б с программной поддержкой. Учитываются правильность документов, согласованность учёта, время обращения и труд всех участвующих сотрудников. Решение о фактической выдаче кредита и подтверждение погашения предоставляет кредитная служба; программа данного контура учитывает утверждённые условия и план.')
 sub(w,'1.3 Функциональные требования',
 'Функциональные требования определяют разрешённые действия и результаты обслуживания. Основные функции обозначены F1–F5; их состав и декомпозиция приведены в разделе 3. Приложение Ж связывает каждую дочернюю функцию с операцией, компонентом, программным модулем и проверкой.')
 rows=[r for r in REQ if r[0].startswith('ФТ-')]
 for start in range(0,len(rows),6):
  table(w,'Функциональные требования'+(' часть 2' if start else ' часть 1'),['Код','Требование','Функции','Проверки'],[(r[0],r[1],r[3],r[5]) for r in rows[start:start+6]],[18,92,22,33])
 paras(w,'При изменении данных программа проверяет полномочия и предметные условия, сохраняет результат и авторство в аудите. Для сведений и документов проверяется право на чтение; формирование отчёта не изменяет исходные банковские факты. Каталог требований и их прослеживаемость составлены с учётом [5].')
 sub(w,'1.4 Нефункциональные требования и критерии качества',
 'Качество определяется соответствием собственных характеристик результата установленным требованиям [8]. Нефункциональные требования относятся к сохранности, оперативности, затратам труда, разграничению доступа, восстановлению и понятности исхода. Они выражены критериями ЦП1–ЦП4, КР1–КР6 и связанными техническими требованиями.',
 'Число правильно завершённых обращений обозначается Q, суммарный ручной труд — L, удельный труд — u=L/Q. В L входят помощь, повторы, исправления и необходимая сверка всех участников. Для времени обслуживания измеряется длительность полного обращения, для сохранности — число критических нарушений.')
 table(w,'Критерии достижения назначения',['Код','Свойство','Измерение','Проектная норма'],GOALS,[13,31,60,61])
 table(w,'Нефункциональные требования и критерии качества',['Код','Свойство','Метрика','Норма'],quality,[14,40,55,56])
 paras(w,'Сравнение А/Б выполняется на тридцати допустимых обращениях: по десять маршрутов «клиент–счёт–карта», «перевод–выписка», «договор–график–сводка». Данные, регламент, состав и квалификация исполнителей фиксируются до серии. Требуются Q_A=Q_B=30, u_B≤0,80u_A, длительность каждого обращения Б≤120 с и отсутствие критических нарушений.',
 'Норма сокращения труда 20 %, состав обращений и временные пределы являются проектными требованиями для согласования до приёмки. Это не результаты измерений банка. Неверный денежный исход, несогласованный график или неразрешённое изменение исключают приёмку независимо от экономии. При отсутствии критических нарушений, но без корректной базы А или полного журнала вывод — «недостаточно свидетельств». Концепция качества показана на А.3, Г.4–Г.5; сравнительная проверка задана И24–И25.')
 sub(w,'1.5 Правила и границы предметной области',
 'Рассматриваются рублёвые счета одного банка и внутрибанковские переводы. В контур не входят межбанковские расчёты, внешние карточные сети, валютный обмен, кассовые пополнения и комиссии. Общая сумма остатков сохраняется для разрешённых переводов текущей книги.',
 'Кредитная часть хранит утверждённый договор и план платежей. Фактическая выдача, принятие кредитного решения и учёт фактической оплаты относятся к кредитной службе. Закрытие договора требует её подтверждающего основания; исходные условия и план сохраняются.')
 table(w,'Предметные ограничения',['Код','Правило'],RULES,[14,151])
 paras(w,'Рабочие места находятся в защищённой сети банка. Предусмотрены четыре учётные роли и до пяти одновременных сеансов. Учёт начинается с подтверждённого среза реестров и начальных остатков. Испытания выполняются отдельно на синтетических данных: основной набор от 1000 предметных записей, нагрузочный — 100 000 переводов.')
 sub(w,'1.6 Требования к назначению, данным и техническим средствам')
 w.h('Требования к назначению',3)
 paras(w,'РН-01–РН-05 требуют связанного обслуживания, единого денежного результата и проверяемых сведений при правильном завершении полного цикла и допустимом расходе труда. Условия УП-01–УП-02 определяют среду, роли и начальные данные. Полный перечень находится в приложении Б.')
 w.h('Концептуальные требования к содержанию данных',3)
 paras(w,'Для счёта сохраняются владелец, отделение и подтверждённый начальный остаток. Карта относится к счёту, перевод — к двум различным счетам. Договор содержит утверждённые условия и полный график; изменение имеет автора и время. Сведения достаточны для выдачи документа и независимой сверки.')
 w.h('Функционально-технические требования',3)
 paras(w,'ФТТ-01–ФТТ-08 требуют атомарного проведения, защиты конкурирующих списаний и повторов, допустимых состояний карты и договора, согласованного графика и отчётов, соблюдения временных пределов и завершения обращения через интерфейс. Процессные основания и проверки приведены в приложении В.')
 w.h('Технические требования',3)
 paras(w,'ТТ-01–ТТ-07 задают серверные проверки, точные деньги numeric(14,2), ключи и связи, документированные интерфейсы, аудит, миграции, права и восстановление. Проектная реализация предусматривает Python, FastAPI, psycopg и PostgreSQL. Состав и параметры раскрыты в разделе 6; комплектность проверяется по ДК-01.')

def write_project_sections(w,table,quality,principles,development,interfaces):
 w.page('2 Декларативная модель предметной области',1)
 sub(w,'2.1 Назначение модели и правила её построения',
 'Декларативная модель описывает объекты, атрибуты, связи и ограничения независимо от порядка программных действий [16]. Её лингвистический минимум выведен из карточки клиента, сведений счёта и карты, распоряжения на перевод, кредитного договора, графика и контрольных документов приложения А.',
 'В нотации Чена сущность обозначается прямоугольником, атрибут — овалом, связь — именованным ромбом; ключ подчёркнут, кратность указана у связи. Рисунки А.1–А.2 раскрывают единую банковскую модель. Повтор контекстной сущности на другом листе не создаёт новый объект.',
 'Модель качества А.3 связывает заинтересованное лицо, потребность, требование, критерий, метрику, норму, испытание, наблюдение, свидетельство и решение. Она определяет смысл оценки: наблюдаемое значение сопоставляется с нормой, а сохранённые сведения обосновывают решение.')
 sub(w,'2.2 Состав сущностей и сохраняемые сведения',
 'Предметная модель включает восемь сущностей и служебный аудит. Логические модели А.4–А.5 раскрывают девять отношений и 63 поля. Полный словарь типов, обязательности, уникальности и смыслов атрибутов приведён в приложении И.')
 table(w,'Сущности декларативной модели',['Сущность / отношение','Сохраняемые сведения'],[
 ('Отделение / branch','Код, город и адрес; место ведения счетов и закрепления сотрудников'),
 ('Клиент / client','Имя, уникальные контакты и момент регистрации'),
 ('Счёт / account','Владелец, отделение, номер, состояние, начальный и текущий остатки'),
 ('Сотрудник / employee','Отделение, логин, имя, роль и признак активности'),
 ('Карта / bank_card','Счёт, номер, даты, состояние и выпустивший сотрудник'),
 ('Перевод / transfer','Два счёта, сумма, ключ команды, состояние, автор и время'),
 ('Договор / loan','Утверждённая сумма, ставка, даты, состояние и основание закрытия'),
 ('Плановый платёж / loan_schedule','Договор, номер, дата, основная часть и проценты'),
 ('Событие аудита / audit_event','Автор, объект, действие, ключ, время и допустимые снимки')],[48,117])
 paras(w,'Клиентская карточка и выписка являются представлениями связанных данных. Классификация выделяет клиентские, карточные, переводные и кредитные операции; ассоциации связывают объект с состоянием и сотрудника с ролью; агрегирование объединяет сведения для документа. Отдельные таблицы для каждого вида отображения не требуются.')
 sub(w,'2.3 Связи и ограничения целостности',
 'Клиент владеет счетами, каждый счёт ведётся одним отделением. Карта обслуживает определённый счёт. Перевод содержит две разные роли счёта — отправителя и получателя. Договор связан со счётом, плановые платежи — с договором. Сотрудник принадлежит отделению и указан автором предметных действий.',
 'На логических схемах показаны все 12 внешних ключей. Ключ графика состоит из (loan_id, payment_no). Связанные записи защищены ON DELETE RESTRICT, идентификаторы неизменяемы. Универсальный entity_id аудита уточняется видом объекта; для строки графика payment_no сохраняется в снимке.',
 'PK, FK, UNIQUE, NOT NULL и CHECK контролируют ключи и построчные ограничения. Достаточность средств и согласованность полного графика требуют проверки нескольких строк в транзакции; такие условия не выражаются произвольным межстрочным CHECK [11].')
 sub(w,'2.4 Переход к хранению и взаимная проверка моделей',
 'Реляционная модель приведена к третьей нормальной форме: значения атомарны; неключевые атрибуты относятся к своему объекту. В loan_schedule дата и суммы определяются всей парой ключа. Реквизиты клиента не повторяются в переводах и договорах, владелец карты определяется через счёт.',
 'Поле balance хранит текущий остаток для проверки достаточности средств. Его согласованность проверяется независимо по opening_balance и завершённым переводам. transferred_at означает инициирование распоряжения, finished_at — завершение или отмену. План договора отделён от фактической выдачи и оплаты.',
 'DFD проверяет достаточность данных: каждый вход и результат функции опирается на известные сведения. Обратная проверка устанавливает, какая операция создаёт запись и кто вправе её изменить. Процессы уточняют условия изменения, а технические спецификации — механизм сохранения и отказа.')

